import{_ as e,c as t,o as a,V as s}from"./chunks/framework.DIWxUZFy.js";const g=JSON.parse('{"title":"knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"TODO/README.md","filePath":"TODO/README.md"}'),i={name:"TODO/README.md"},n=s(`<h1 id="knowledge" tabindex="-1">knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;knowledge&quot;">​</a></h1><p><a href="https://github.com/kalisio/knowledge/releases" target="_blank" rel="noreferrer"><img src="https://img.shields.io/github/v/tag/kalisio/knowledge?sort=semver&amp;label=latest" alt="Latest Release"></a><a href="https://github.com/kalisio/knowledge/actions/workflows/main.yml" target="_blank" rel="noreferrer"><img src="https://github.com/kalisio/knowledge/actions/workflows/main.yml/badge.svg" alt="CI"></a><a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-MIT-yellow.svg" alt="License: MIT"></a></p><p>Retrieval-augmented question-answering over the documentation and source code of the <a href="https://kalisio.com" target="_blank" rel="noreferrer">Kalisio platform</a> and its open-source projects (<a href="https://kalisio.github.io/kdk/" target="_blank" rel="noreferrer">KDK</a>, <a href="https://kalisio.github.io/kano/" target="_blank" rel="noreferrer">Kano</a> and others). Documentation and code are chunked, embedded with <a href="https://www.sbert.net/" target="_blank" rel="noreferrer">sentence-transformers</a>, indexed in <a href="https://qdrant.tech/" target="_blank" rel="noreferrer">Qdrant</a>, and queried through a provider-agnostic LLM client (Anthropic Claude, OpenAI, Mistral, or Kimi/Moonshot — selected from <code>MODEL_URL</code>).</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Miniconda or Anaconda</li><li>Docker (no local image building required — images are pulled from Docker Hub)</li><li>Optional: Ollama, either local or on a machine reachable on the LAN</li></ul><h2 id="install-conda" tabindex="-1">Install Conda <a class="header-anchor" href="#install-conda" aria-label="Permalink to &quot;Install Conda&quot;">​</a></h2><p>Install Miniconda with the official installer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O /tmp/miniconda_installer.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/miniconda_installer.sh -b -p ~/miniconda3</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/miniconda3/bin/conda init bash</span></span></code></pre></div><p>Reload your shell:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span></code></pre></div><p>Check installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">conda</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="install-project-dependencies" tabindex="-1">Install Project Dependencies <a class="header-anchor" href="#install-project-dependencies" aria-label="Permalink to &quot;Install Project Dependencies&quot;">​</a></h2><p>The project uses Python 3.11, managed through <code>environment.yml</code>.</p><p>Create the conda environment and install all dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">conda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env create -f environment.yml</span></span></code></pre></div><p>Activate the environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">conda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activate knowledge</span></span></code></pre></div><h2 id="gpu-acceleration-optional" tabindex="-1">GPU acceleration (optional) <a class="header-anchor" href="#gpu-acceleration-optional" aria-label="Permalink to &quot;GPU acceleration (optional)&quot;">​</a></h2><p>The chunking, embedding, retrieval and notebook code paths use <code>sentence-transformers</code> with automatic device detection: CUDA if available, CPU otherwise. No code changes are needed either way — each run prints the device it picked, for example <code>[embed] cuda (NVIDIA GeForce RTX 3060 Ti)</code> or <code>[embed] cpu (CUDA not available)</code>. Batch size is selected automatically by <a href="./src/embedding_utils.py.html">src/embedding_utils.py</a> based on the active device.</p><h3 id="verify-your-setup" tabindex="-1">Verify your setup <a class="header-anchor" href="#verify-your-setup" aria-label="Permalink to &quot;Verify your setup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch; print(torch.cuda.is_available(), torch.version.cuda)&quot;</span></span></code></pre></div><ul><li><code>True 12.x</code> — you&#39;re set, embedding will use CUDA.</li><li><code>False None</code> — CPU mode. Fine for small corpora, just slower (see benchmarks below).</li><li><code>False 13.x</code> (or any CUDA version newer than your NVIDIA driver supports) — your torch CUDA runtime is newer than your driver. Reinstall torch with a matching wheel. For driver 535 (CUDA ≤ 12.2):<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall -y torch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install --index-url https://download.pytorch.org/whl/cu121 torch</span></span></code></pre></div></li></ul><p>Run <code>nvidia-smi</code> to check your driver&#39;s maximum supported CUDA version.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>The codebase is organised as a few independent modules under <a href="./src/">src/</a>:</p><table><thead><tr><th>Module</th><th>Role</th></tr></thead><tbody><tr><td><a href="./src/corpus_filter/">src/corpus_filter/</a></td><td>Corpus discovery and profile-driven filtering. Public entry: <code>scan_corpus(profile=...)</code>; profiles in <code>profiles.py</code>, walker in <code>engine.py</code>.</td></tr><tr><td><a href="./src/chunking/">src/chunking/</a></td><td>Production chunkers per file type. Every function returns <code>list[dict]</code> with <code>text</code> (breadcrumb-prefixed) and <code>metadata</code> (structured fields for retriever / reranker / UI).</td></tr><tr><td><a href="./src/embedding_utils.py.html">src/embedding_utils.py</a></td><td>Automatic device + batch-size selection for <code>sentence-transformers</code>.</td></tr><tr><td><a href="./src/rag_system/">src/rag_system/</a></td><td>Runtime components for the v1 RAG service: <code>config.py</code> (env-driven settings), <code>embedding.py</code>, <code>qdrant_store.py</code>, <code>llm.py</code> (Ollama / Anthropic).</td></tr><tr><td><a href="./src/api/">src/api/</a></td><td>FastAPI service: <code>app.py</code> (HTTP layer), <code>handlers.py</code> (RAG pipeline), <code>schemas.py</code> (request / response models), <code>main.py</code> (entry point).</td></tr><tr><td><a href="./src/retrieval_metrics.py.html">src/retrieval_metrics.py</a></td><td>Deterministic retrieval metrics (recall@k, source coverage, …) shared across nb02–nb06.</td></tr></tbody></table><p>The chunking package exposes one winner per file type, all selected through the matching notebook:</p><table><thead><tr><th>File type</th><th>Function</th><th>Strategy</th><th>Notebook</th></tr></thead><tbody><tr><td>Markdown</td><td><code>chunk_markdown</code></td><td>AST-Merge + Breadcrumb (D)</td><td>nb02</td></tr><tr><td>JS / <code>.mjs</code></td><td><code>chunk_js</code></td><td>Recursive JS + breadcrumb</td><td>nb03</td></tr><tr><td>Vue SFC</td><td><code>chunk_vue</code></td><td>SFC dispatcher + expanded breadcrumb</td><td>nb03</td></tr><tr><td>JSON</td><td><code>chunk_json</code></td><td>Category-aware key split + breadcrumb</td><td>nb04</td></tr><tr><td>any</td><td><code>chunk_files</code></td><td>extension dispatcher (calls the right per-type chunker)</td><td>—</td></tr></tbody></table><h2 id="api-service" tabindex="-1">API service <a class="header-anchor" href="#api-service" aria-label="Permalink to &quot;API service&quot;">​</a></h2><p>The first runnable system component is a FastAPI retriever at <a href="./api/">api/</a>. Run it locally with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api.main</span></span></code></pre></div><p>By default it listens on <code>127.0.0.1:8000</code> (override via <code>HOST</code> / <code>PORT</code> environment variables). Endpoints:</p><table><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/health</code></td><td>Health check</td></tr><tr><td><code>POST</code></td><td><code>/ask</code></td><td>Body <code>{&quot;question&quot;: &quot;...&quot;}</code> → LLM answer plus the retrieved source chunks</td></tr></tbody></table><p>The API image is published to Docker Hub as <code>kalisio/knowledge-api:latest</code> and <code>kalisio/knowledge-api:\${git_sha}</code> — see <a href=".github/workflows/main.yml">.github/workflows/main.yml</a>. The CI workflow needs the <code>DOCKERHUB_USERNAME</code> and <code>DOCKERHUB_TOKEN</code> repository secrets.</p><h3 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h3><p><a href="./.env.example.html">.env.example</a> lists every variable read by <a href="./src/rag_system/config.py.html">src/rag_system/config.py</a>. Copy it to <code>.env</code> for local runs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example .env</span></span></code></pre></div><h2 id="llm-configuration" tabindex="-1">LLM Configuration <a class="header-anchor" href="#llm-configuration" aria-label="Permalink to &quot;LLM Configuration&quot;">​</a></h2><p>The RAG service uses a single OpenAI-compatible client for all four providers; the provider label is detected from <code>MODEL_URL</code>:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MODEL_API_KEY=        # required</span></span>
<span class="line"><span>MODEL_NAME=           # required</span></span>
<span class="line"><span>MODEL_URL=            # required; must match anthropic|openai|mistral|kimi|moonshot</span></span></code></pre></div><p>If any of the three variables is empty, or if <code>MODEL_URL</code> does not match a known provider, the API raises <code>RuntimeError</code> at startup. All four providers expose <code>/v1/chat/completions</code>, so a single <code>OpenAI(api_key=MODEL_API_KEY, base_url=MODEL_URL)</code> instance with <code>model=MODEL_NAME</code> covers them all. Adding a new provider only requires adding one more <code>if &quot;&lt;name&gt;&quot; in url</code> branch.</p><table><thead><tr><th>Provider</th><th><code>MODEL_NAME</code> example</th><th><code>MODEL_URL</code></th></tr></thead><tbody><tr><td>Anthropic Claude</td><td><code>claude-sonnet-4-20250514</code></td><td><code>https://api.anthropic.com/v1</code></td></tr><tr><td>OpenAI</td><td><code>gpt-4o-mini</code></td><td><code>https://api.openai.com/v1</code></td></tr><tr><td>Mistral</td><td><code>mistral-large-latest</code></td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>Kimi / Moonshot</td><td><code>kimi-latest</code></td><td><code>https://api.moonshot.cn/v1</code></td></tr></tbody></table><h2 id="project-data-layout" tabindex="-1">Project Data Layout <a class="header-anchor" href="#project-data-layout" aria-label="Permalink to &quot;Project Data Layout&quot;">​</a></h2><p>The corpus is expected under <code>data/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>data/&lt;repo&gt;/&lt;sub-tree&gt;</span></span></code></pre></div><p>Default scan root used by <code>scan_corpus</code> is <code>data/</code>. The KDK documentation set sits at <code>data/kdk/docs</code>. If you start from a ZIP archive, extract it under <code>data/</code> keeping the per-repo folder layout.</p><h2 id="notebooks" tabindex="-1">Notebooks <a class="header-anchor" href="#notebooks" aria-label="Permalink to &quot;Notebooks&quot;">​</a></h2><p>The research history is captured in six notebooks under <a href="./notebooks/">notebooks/</a>, with the matching helpers under <code>experiments/nbXX_*/</code>.</p><table><thead><tr><th>#</th><th>Notebook</th><th>Topic</th><th>Status</th></tr></thead><tbody><tr><td>nb01</td><td><a href="./notebooks/nb01_corpus_discovery.ipynb.html">nb01_corpus_discovery.ipynb</a></td><td>Corpus discovery and filtering profiles, source for <a href="./src/corpus_filter/">src/corpus_filter/</a>.</td><td>done</td></tr><tr><td>nb02</td><td><a href="./notebooks/nb02_markdown_chunking_strategies.ipynb.html">nb02_markdown_chunking_strategies.ipynb</a></td><td>Markdown chunking strategies. Winner: <code>D_ast_breadcrumb</code> (chunk_size=500), 100% code-block integrity, 2× the bundle efficiency of the RCT baseline. Production code in <a href="./src/chunking/markdown.py.html">src/chunking/markdown.py</a>.</td><td>done</td></tr><tr><td>nb03</td><td><a href="./notebooks/nb03_js_vue_chunking.ipynb.html">nb03_js_vue_chunking.ipynb</a></td><td>JS and Vue SFC chunking strategies; ~97% accuracy on Vue split tests. Adds BM25 + RRF for hybrid retrieval. Production code in <a href="./src/chunking/js.py.html">src/chunking/js.py</a> and <a href="./src/chunking/vue.py.html">src/chunking/vue.py</a>.</td><td>done</td></tr><tr><td>nb04</td><td><a href="./notebooks/nb04_json_chunking.ipynb.html">nb04_json_chunking.ipynb</a></td><td>JSON chunking with category-aware key splitting. Production code in <a href="./src/chunking/json_chunking.py.html">src/chunking/json_chunking.py</a>.</td><td>done</td></tr><tr><td>nb05</td><td><a href="./notebooks/nb05_embedding_evaluation.ipynb.html">nb05_embedding_evaluation.ipynb</a></td><td>Embedding model evaluation on a 200-question bilingual (FR / EN) gold set (<a href="outputs/nb05_gold.json">outputs/nb05_gold.json</a>). Recommends <code>Qwen/Qwen3-Embedding-0.6B</code>; <code>intfloat/multilingual-e5-large</code> is kept as a strong baseline.</td><td>done</td></tr><tr><td>nb06</td><td><a href="./notebooks/nb06_qdrant_index_and_eval.ipynb.html">nb06_qdrant_index_and_eval.ipynb</a></td><td>Reproducible Qdrant index from the selected corpus chunks; re-runs the nb05 evaluation against Qdrant to validate dense / hybrid / reranked retrieval at production scale.</td><td>in progress</td></tr></tbody></table><h3 id="reproducing-the-chunking-benchmark-nb02" tabindex="-1">Reproducing the chunking benchmark (nb02) <a class="header-anchor" href="#reproducing-the-chunking-benchmark-nb02" aria-label="Permalink to &quot;Reproducing the chunking benchmark (nb02)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Generate the gold query set from KDK docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/nb02_chunking_md/build_gold_query_set.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Run deterministic retrieval metrics (requires Qdrant with ingested collections)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/nb02_chunking_md/evaluate_nb02_deterministic.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Parameter sweep on the winner strategy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/nb02_chunking_md/nb02_sweep_winner.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Code-generation experiment (dry-run generates context bundles)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/nb02_chunking_md/nb02_codegen_experiment.py --dry-run</span></span></code></pre></div><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Run the full suite:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><p>Coverage:</p><table><thead><tr><th>File</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./tests/test_chunking_golden.py.html">tests/test_chunking_golden.py</a></td><td>End-to-end golden tests for the chunking package (marker: <code>golden</code>, requires the embedding model and the KDK docs).</td></tr><tr><td><a href="./tests/test_corpus_filter_profiles.py.html">tests/test_corpus_filter_profiles.py</a></td><td>Corpus filter profiles and <code>FilterConfig</code> resolution.</td></tr><tr><td><a href="./tests/test_nb05_augmentation.py.html">tests/test_nb05_augmentation.py</a></td><td>nb05 query augmentation helpers.</td></tr><tr><td><a href="./tests/test_nb06_qdrant_index.py.html">tests/test_nb06_qdrant_index.py</a></td><td>nb06 ingestion / index helpers.</td></tr><tr><td><a href="./tests/test_system_v1.py.html">tests/test_system_v1.py</a></td><td>System v1 FastAPI service.</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Activate the conda environment with <code>conda activate knowledge</code> before running scripts.</li><li>Generated files under <code>outputs/</code> are local artifacts and should not be treated as source files.</li><li><code>qdrant_data/</code> is local runtime data and should not be committed.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Licensed under the <a href="./LICENSE.html">MIT license</a>.</p><p>Copyright (c) 2017-present <a href="https://kalisio.com" target="_blank" rel="noreferrer">Kalisio</a></p><p><a href="https://kalisio.com" target="_blank" rel="noreferrer"><img src="https://kalisio.github.io/kalisioscope/kalisio/kalisio-logo-black-256x84.png" alt="Kalisio"></a></p>`,63),o=[n];function r(d,l,c,h,p,u){return a(),t("div",null,o)}const b=e(i,[["render",r]]);export{g as __pageData,b as default};
